"""Additive controls in the existing editor, Outreach, and Reports views."""

# ruff: noqa: E501 - existing inline frontend architecture.

ENGAGEMENT_SCRIPT = r"""<script>
document.addEventListener('DOMContentLoaded',()=>{
const el=id=>document.getElementById(id);
async function request(url,body){const response=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Request failed');return data;}
function element(tag,text,cls){const item=document.createElement(tag);if(text)item.textContent=text;if(cls)item.className=cls;return item;}
const outreach=el('outreachView');
if(outreach){const box=element('div',null,'view-heading');box.append(element('h2','Incoming replies'));const refresh=element('button','Sync replies','btn');refresh.type='button';const status=element('p',null,'sub'),list=element('div');box.append(refresh,status,list);outreach.append(box);
async function replies(sync=false){refresh.disabled=true;try{if(sync)await request('/api/enhancements/replies/sync',{});const [items,settings]=await Promise.all([request('/api/enhancements/replies'),request('/api/enhancements/status')]);list.replaceChildren();status.textContent=(settings.ai_configured?'AI configured. ':'AI classification needs backend configuration. ')+(settings.sync_error||'')+(settings.last_sync?' Last sync: '+new Date(settings.last_sync).toLocaleString(): ' No successful reply sync yet.')+(settings.sync_in_progress?' History sync is still in progress.':'');refresh.disabled=!settings.reply_sync_available;for(const item of items){const row=element('div',null,'report-card');row.append(element('strong',item.name+' · '+(item.classification||'Classification pending')),element('p',item.content||'[Attachment-only reply]'),element('small','Follow-ups paused · '+(item.classification_source||'Awaiting AI classification'),'sub'));list.append(row);}if(!items.length)list.textContent='No synced replies for saved leads.';}catch(error){status.textContent=error.message;refresh.disabled=false;}}
refresh.onclick=()=>replies(true);replies();window.addEventListener('hashchange',()=>{if(location.hash==='#outreach')replies();});setInterval(()=>{if(location.hash==='#outreach')replies();},30000);}
const originalOpen=openEditor;let editorSerial=0;
openEditor=function(id){originalOpen(id);const serial=++editorSerial,grid=el('formGrid'),form=el('editForm');const section=element('div',null,'field full');section.append(element('label','AI draft assistance'));const status=element('p',null,'sub');status.setAttribute('role','status');const context=element('textarea');context.placeholder='Optional: your verified offer or purpose (used exactly as supplied)';context.maxLength=1000;context.setAttribute('aria-label','Verified message context');const preview=element('textarea');preview.setAttribute('aria-label','Editable AI suggestion');preview.hidden=true;const use=element('button','Use reviewed suggestion in draft','btn');use.type='button';use.hidden=true;let kind='connection';
for(const [type,label] of [['connection','Personalize connection draft'],['follow_up','Suggest follow-up']]){const button=element('button',label,'btn');button.type='button';button.onclick=async()=>{button.disabled=true;use.hidden=true;preview.hidden=true;status.textContent='Preparing suggestion…';try{const field=form.elements.namedItem(type==='connection'?'connection_message':'follow_up_message');const data=await request('/api/enhancements/leads/'+id+'/draft',{kind:type,context:context.value,existing:field.value});if(serial!==editorSerial||!editor.open)return;kind=type;preview.value=data.draft;preview.hidden=false;use.hidden=false;status.textContent='Review and edit below. '+(data.followups_paused?'Follow-ups remain paused. ':'')+'Nothing has been saved or sent.';}catch(error){if(serial===editorSerial)status.textContent=error.message;}finally{button.disabled=false;}};section.append(button);}
use.onclick=()=>{if(serial!==editorSerial)return;form.elements.namedItem(kind==='connection'?'connection_message':'follow_up_message').value=preview.value;status.textContent='Copied to editable draft. Click Save client to persist; existing authorization is still required to send.';};section.append(context,preview,use,status);grid.append(section);
request('/api/enhancements/leads/'+id+'/conversation').then(data=>{if(serial!==editorSerial||!editor.open)return;const conversation=element('div',null,'field full');conversation.append(element('label','Conversation history'));if(data.followup_hold)conversation.append(element('p','Follow-ups paused: '+data.followup_hold,'sub'));for(const message of data.messages.slice(-20))conversation.append(element('div',(message.outgoing?'You: ':'Recipient: ')+(message.content||'[Attachment]')+(message.classification?' · '+message.classification:''),'profile-value'));if(!data.messages.length)conversation.append(element('p','No synced conversation yet.','sub'));grid.append(conversation);}).catch(error=>{if(serial===editorSerial)status.textContent=error.message;});};
});
</script>"""
